-- Botswana: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'bw-ebilling-announced', id, '2024-02-05', 1, 'https://dailynews.gov.bw/news-detail/77665', 0, '[]', NULL, 'none', 'unreviewed' FROM countries WHERE code = 'BW';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('bw-ebilling-announced', 'en', 'BURS announces an e-billing programme', 'BURS announced electronic billing as a three-year project, with phase one scheduled for December 2024. No legal instrument existed at this point and the phase-one date was not met.', '["Treat as background, not as a deadline"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'bw-taa-in-force', id, '2026-07-01', 0, 'https://kpmg.com/us/en/taxnewsflash/news/2026/07/botswana-corporate-tax-dmtt-vat-enacted.html', 1, '[{"label": "BURS e-Tax", "url": "https://eservices.burs.org.bw/"}]', NULL, 'none', 'live' FROM countries WHERE code = 'BW';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('bw-taa-in-force', 'en', 'Tax Administration Act 2026 takes effect, harmonising record retention at eight years', 'The Tax Administration Act, 2026 (Act 14 of 2026) came into force, harmonising record retention at eight years across all tax types and defining the electronic billing system that commences nine months later.', '["Retain VAT and income tax records for eight years", "Confirm records are held in Botswana"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'bw-ebilling-commences', id, '2027-04-01', 0, 'https://www.mondaq.com/southafrica/sales-taxes-vat-gst/1818540/africa-tax-in-brief-14-july-2026', 1, '[{"label": "BURS e-Tax", "url": "https://eservices.burs.org.bw/"}]', 'expected', 'b2b', 'live' FROM countries WHERE code = 'BW';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('bw-ebilling-commences', 'en', 'The electronic billing system commences for VAT-registered persons', 'The Tax Administration Act sets commencement of the electronic billing system at nine months from the Act''s own commencement. VAT-registered persons must issue receipts through approved devices transmitting data directly to BURS.', '["Confirm whether your billing systems can transmit to BURS", "Watch for the technical specification, not yet published"]');

